+import rowsData from './rows.json' with { type: 'json' };
+
+const ROWS = rowsData;
+const CURSOR_PREFIX = 'page:';
+const CURSOR_RE = /^page:\d+$/;
+
+function encodeCursor(index) {
+  return Buffer.from(CURSOR_PREFIX + index, 'utf8').toString('base64');
+}
+
+function decodeCursor(cursor) {
+  if (typeof cursor !== 'string' || cursor.length === 0) {
+    throw invalidCursor();
+  }
+  let decoded;
+  try {
+    decoded = Buffer.from(cursor, 'base64').toString('utf8');
+  } catch {
+    throw invalidCursor();
+  }
+  if (!CURSOR_RE.test(decoded)) {
+    throw invalidCursor();
+  }
+  const index = Number(decoded.slice(CURSOR_PREFIX.length));
+  if (!Number.isInteger(index) || index < 0 || index > ROWS.length) {
+    throw invalidCursor();
+  }
+  return index;
+}
+
+function invalidCursor() {
+  const err = new Error('Invalid cursor');
+  err.code = 'INVALID_CURSOR';
+  return err;
+}
+
+function badArgs(message) {
+  const err = new Error(message);
+  err.code = -32602;
+  return err;
+}
+
+function isPlainObject(v) {
+  return v !== null && typeof v === 'object' && !Array.isArray(v);
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'page',
+      description: 'Page over rows.json. Returns rows and next_cursor when more rows remain.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          limit: { type: 'integer', minimum: 1, maximum: 2 },
+          cursor: { type: 'string' }
+        },
+        required: ['limit']
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'page') {
+    const err = new Error('Unknown tool');
+    err.code = -32601;
+    throw err;
+  }
+
+  if (!isPlainObject(args)) {
+    throw badArgs('arguments must be an object');
+  }
+
+  if (!Object.prototype.hasOwnProperty.call(args, 'limit')) {
+    throw badArgs('limit is required');
+  }
+  const { limit } = args;
+  if (!Number.isInteger(limit) || limit < 1 || limit > 2) {
+    throw badArgs('limit must be an integer between 1 and 2');
+  }
+
+  const hasCursor = Object.prototype.hasOwnProperty.call(args, 'cursor');
+
+  let index = 0;
+  if (hasCursor) {
+    const cursor = args.cursor;
+    if (cursor === undefined) {
+      // treated as "no cursor provided"; start from the beginning
+    } else if (typeof cursor !== 'string') {
+      throw badArgs('cursor must be a string');
+    } else {
+      // a provided string cursor must be valid; empty/garbage/stale is an error
+      index = decodeCursor(cursor);
+    }
+  }
+
+  const slice = ROWS.slice(index, index + limit);
+  const nextIndex = index + limit;
+  const result = { rows: slice };
+  if (nextIndex < ROWS.length) {
+    result.next_cursor = encodeCursor(nextIndex);
+  }
+  return result;
+}
